d text-slate-400">Match time<input class="form-control mt-2" type="datetime-local" name="match_time" required value="<?= h($tournament?date('Y-m-d\TH:i',strtotime((string)$tournament['match_time'].' UTC')):'') ?>"></label><label class="text-xs font-bold text-slate-400">Room credentials release<input class="form-control mt-2" type="datetime-local" name="room_release_at" required value="<?= h($tournament?date('Y-m-d\TH:i',strtotime((string)$tournament['room_release_at'].' UTC')):'') ?>"></label><label class="text-xs font-bold text-slate-400">Status<select class="form-control mt-2" name="status"><?php foreach(['draft','open','locked','live'] as $status): ?><option value="<?= h($status) ?>" <?= ($tournament['status']??'draft')===$status?'selected':'' ?>><?= h(ucfirst($status)) ?></option><?php endforeach; ?></select></label><label class="text-xs font-bold text-slate-400 sm:col-span-2">Description<textarea class="form-control mt-2 min-h-24" name="description" maxlength="5000" required><?= h($tournament['description']??'') ?></textarea></label><label class="text-xs font-bold text-slate-400 sm:col-span-2">Rules<textarea class="form-control mt-2 min-h-24" name="rules" maxlength="5000" required><?= h($tournament['rules']??'') ?></textarea></label><label class="text-xs font-bold text-slate-400 sm:col-span-2">Banner image · JPG, PNG or WebP, max 3 MB<input class="form-control mt-2" type="file" name="banner" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"><?php if($tournament['banner_path']??null): ?><span class="mt-1 block text-[10px] font-normal text-slate-500">Current banner is retained if no new file is selected.</span><?php endif; ?></label></div>
